: [1, 1, 1]}, {"id": "00000000-0000-4000-8000-000000001203", "recordId": "00000000-0000-4000-8000-000000001003", "mediaId": "00000000-0000-4000-8000-000000001103", "roomId": "00000000-0000-4000-8000-000000000010", "slotId": "wall-left-1", "position": [-4.71, 2, 0], "rotation": [0, 1.5707963267948966, 0], "scale": [1, 1, 1]}, {"id": "00000000-0000-4000-8000-000000001201", "recordId": "00000000-0000-4000-8000-000000001001", "mediaId": "00000000-0000-4000-8000-000000001101", "roomId": "00000000-0000-4000-8000-000000000010", "slotId": "wall-right-1", "position": [4.71, 2, 0], "rotation": [0, -1.5707963267948966, 0], "scale": [1, 1, 1]}, {"id": "00000000-0000-4000-8000-000000001202", "recordId": "00000000-0000-4000-8000-000000001002", "mediaId": "00000000-0000-4000-8000-000000001102", "roomId": "00000000-0000-4000-8000-000000000010", "slotId": "wall-left-2", "position": [-4.71, 2, -3.2], "rotation": [0, 1.5707963267948966, 0], "scale": [1, 1, 1]}], "exhibition": {"id": "00000000-0000-4000-8000-000000000020", "title": "Corpos, fios e territórios", "subtitle": "Acervo Trans de Mato Grosso", "notice": "Prévia curatorial independente. Painéis editoriais sem reproduzir obras originais.", "status": "published", "beginsAt": "", "endsAt": ""}}$published$::jsonb;
 perform desvio_private.validate_snapshot(draft,false);
 perform desvio_private.write_version(c.draft_version,draft);
 insert into public.desvio_versions(collection_id,exhibition) values(c.id,published->'exhibition') returning id into v;
 perform desvio_private.write_version(v,published);
